method.description:
Registers a [NetwTransport] subclass. A transport allows to give more meanings to the underlying [MultipalyerPeer] class the transport wraps. [code]false[/code] when this session already registered a transport of that class, [code]true[/code] otherwise.
[codeblock]
func _ready() -> void:
    var c := Netw.connection(self)
    if c.register_transport(MyRelayTransport):
        c.create_peer(
                MyRelayTransport,
                NetwMultiplayer.TRANSPORT_MODE_HOST,
                "", {region = "eu"}, take_the_peer)
[/codeblock]
